import { scrollToBottom } from '../utils/helpers.js';

export class ChatContainer {
  constructor(container, options = {}) {
    this.container = container;
    this.messages = options.messages || [];
    this.placeholder = options.placeholder || '输入问题...';
    this.render();
  }

  render() {
    this.container.innerHTML = `
      <div class="chat-container">
        <div class="chat-messages" id="chat-messages-${this.container.id}">
          ${this.renderMessages()}
        </div>
        <div class="chat-input">
          <input type="text" id="chat-input-${this.container.id}" placeholder="${this.placeholder}">
          <button class="btn btn-primary" id="chat-send-${this.container.id}">发送</button>
        </div>
      </div>
    `;

    this.bindEvents();
  }

  renderMessages() {
    return this.messages
      .map((msg) => {
        const isUser = msg.role === 'user';
        return `
          <div class="chat-message" style="flex-direction:${isUser ? 'row-reverse' : 'row'}">
            <div class="chat-avatar ${isUser ? 'user' : ''}">${isUser ? 'U' : 'AI'}</div>
            <div class="chat-bubble ${isUser ? 'user' : ''}">${msg.content}</div>
          </div>
        `;
      })
      .join('');
  }

  bindEvents() {
    const input = document.getElementById(`chat-input-${this.container.id}`);
    const sendBtn = document.getElementById(`chat-send-${this.container.id}`);

    const sendMessage = () => {
      const content = input.value.trim();
      if (!content) return;

      const userMsg = { id: Date.now(), role: 'user', content };
      this.addMessage(userMsg);
      input.value = '';

      this.onSendMessage?.(content);
    };

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        sendMessage();
      }
    });

    sendBtn.addEventListener('click', sendMessage);
  }

  addMessage(message) {
    this.messages.push(message);
    const messagesContainer = document.getElementById(`chat-messages-${this.container.id}`);
    const isUser = message.role === 'user';

    const msgHTML = `
      <div class="chat-message" style="flex-direction:${isUser ? 'row-reverse' : 'row'}">
        <div class="chat-avatar ${isUser ? 'user' : ''}">${isUser ? 'U' : 'AI'}</div>
        <div class="chat-bubble ${isUser ? 'user' : ''}">${message.content}</div>
      </div>
    `;

    messagesContainer.insertAdjacentHTML('beforeend', msgHTML);
    scrollToBottom(messagesContainer);
  }

  setMessages(messages) {
    this.messages = messages;
    this.render();
  }

  setOnSendMessage(callback) {
    this.onSendMessage = callback;
  }
}

export class UserChatContainer {
  constructor(container, options = {}) {
    this.container = container;
    this.messages = options.messages || [];
    this.suggestions = options.suggestions || [];
    this.showWelcome = options.showWelcome !== false;
    this.render();
  }

  render() {
    this.container.innerHTML = `
      <div class="user-chat-messages" id="user-chat-messages-${this.container.id}">
        ${this.showWelcome && this.messages.length === 0 ? this.renderWelcome() : ''}
        ${this.renderMessages()}
      </div>
      <div class="user-chat-input-area">
        <div class="user-chat-input-wrap">
          <input
            type="text"
            class="user-chat-input"
            id="user-chat-input-${this.container.id}"
            placeholder="输入您的问题..."
          />
          <button class="user-send-btn" id="user-chat-send-${this.container.id}">发送</button>
        </div>
        <div class="user-chat-hint">按 Enter 发送</div>
      </div>
    `;

    this.bindEvents();
  }

  renderWelcome() {
    return `
      <div class="user-welcome">
        <div class="user-welcome-icon">🤖</div>
        <h3>欢迎使用知识库问答</h3>
        <p>我是您的智能助手，可以帮您查找 <strong>产品文档中心</strong> 中的信息。</p>
        <div class="user-suggestions">
          ${this.suggestions
            .map(
              (suggestion) => `
            <button class="suggestion-chip">${suggestion}</button>
          `
            )
            .join('')}
        </div>
      </div>
    `;
  }

  renderMessages() {
    return this.messages
      .map((msg) => {
        const isUser = msg.role === 'user';
        return `
          <div class="user-message user-message-${isUser ? 'user' : 'bot'}">
            <div class="user-message-avatar">
              <div class="${isUser ? 'user-avatar-small' : 'bot-avatar'}">
                ${isUser ? 'U' : 'AI'}
              </div>
            </div>
            <div class="user-message-content">
              <div class="user-message-bubble">${msg.content}</div>
              <div class="user-message-time">${msg.time}</div>
            </div>
          </div>
        `;
      })
      .join('');
  }

  bindEvents() {
    const input = document.getElementById(`user-chat-input-${this.container.id}`);
    const sendBtn = document.getElementById(`user-chat-send-${this.container.id}`);
    const suggestionChips = this.container.querySelectorAll('.suggestion-chip');

    const sendMessage = (content) => {
      const text = content || input.value.trim();
      if (!text) return;

      const now = new Date();
      const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const userMsg = { id: Date.now(), role: 'user', content: text, time };
      this.addMessage(userMsg);
      input.value = '';

      this.onSendMessage?.(text);
    };

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        sendMessage();
      }
    });

    sendBtn.addEventListener('click', () => sendMessage());

    suggestionChips.forEach((chip) => {
      chip.addEventListener('click', () => {
        sendMessage(chip.textContent);
      });
    });
  }

  addMessage(message) {
    if (this.showWelcome && this.messages.length === 0) {
      const welcomeEl = this.container.querySelector('.user-welcome');
      if (welcomeEl) {
        welcomeEl.remove();
      }
    }

    this.messages.push(message);
    const messagesContainer = document.getElementById(`user-chat-messages-${this.container.id}`);
    const isUser = message.role === 'user';

    const msgHTML = `
      <div class="user-message user-message-${isUser ? 'user' : 'bot'}">
        <div class="user-message-avatar">
          <div class="${isUser ? 'user-avatar-small' : 'bot-avatar'}">
            ${isUser ? 'U' : 'AI'}
          </div>
        </div>
        <div class="user-message-content">
          <div class="user-message-bubble">${message.content}</div>
          <div class="user-message-time">${message.time}</div>
        </div>
      </div>
    `;

    messagesContainer.insertAdjacentHTML('beforeend', msgHTML);
    scrollToBottom(messagesContainer);
  }

  setMessages(messages) {
    this.messages = messages;
    this.render();
  }

  setOnSendMessage(callback) {
    this.onSendMessage = callback;
  }
}
